import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class IncrementallyUpdatedFilterPredicateGeneratorRunTests {

  @TempDir
  Path temporaryDirectory;

  @Test
  void runWritesCompleteBuilderSourceAndClosesOutputFile() throws Exception {
    Path output = temporaryDirectory.resolve("IncrementallyUpdatedFilterPredicateBuilder.java");

    IncrementallyUpdatedFilterPredicateGenerator generator =
        new IncrementallyUpdatedFilterPredicateGenerator(output.toFile());
    generator.run();

    String source = Files.readString(output, StandardCharsets.UTF_8);

    assertTrue(source.startsWith("package org.apache.parquet.filter2.recordlevel;"));
    assertTrue(source.contains(
        "public class IncrementallyUpdatedFilterPredicateBuilder "
            + "extends IncrementallyUpdatedFilterPredicateBuilderBase"));
    assertTrue(source.contains(
        "public IncrementallyUpdatedFilterPredicateBuilder(List<PrimitiveColumnIO> leaves)"));

    assertTrue(source.contains("visit(Eq<T> pred)"));
    assertTrue(source.contains("visit(NotEq<T> pred)"));
    assertTrue(source.contains("visit(In<T> pred)"));
    assertTrue(source.contains("visit(NotIn<T> pred)"));
    assertTrue(source.contains("visit(Contains<T> pred)"));
    assertTrue(source.contains("visit(Lt<T> pred)"));
    assertTrue(source.contains("visit(LtEq<T> pred)"));
    assertTrue(source.contains("visit(Gt<T> pred)"));
    assertTrue(source.contains("visit(GtEq<T> pred)"));
    assertTrue(source.contains("visit(UserDefined<T, U> pred)"));
    assertTrue(source.contains("visit(LogicalNotUserDefined<T, U> notPred)"));

    for (String type : new String[] {"Integer", "Long", "Boolean", "Float", "Double", "Binary"}) {
      assertTrue(source.contains("clazz.equals(" + type + ".class)"),
          "Generated source must handle " + type + " predicates");
    }

    assertTrue(source.contains("Operator < not supported for Boolean"));
    assertTrue(source.contains("Operator <= not supported for Boolean"));
    assertTrue(source.contains("Operator > not supported for Boolean"));
    assertTrue(source.contains("Operator >= not supported for Boolean"));

    assertTrue(source.endsWith("}\n"));

    Files.writeString(output, "still writable", StandardCharsets.UTF_8);
    assertEquals("still writable", Files.readString(output, StandardCharsets.UTF_8));
  }
}

