  @Test
  void generatedClassContainsExpectedStructure(@TempDir File tempDir) throws IOException {
    File out = new File(tempDir, "IncrementallyUpdatedFilterPredicateBuilder.java");
    IncrementallyUpdatedFilterPredicateGenerator generator =
        new IncrementallyUpdatedFilterPredicateGenerator(out);
    generator.run();

    String content = Files.readString(out.toPath(), StandardCharsets.UTF_8);

    // Basic structural checks derived from the specification/spec generator output
    assertTrue(content.contains("public class IncrementallyUpdatedFilterPredicateBuilder extends IncrementallyUpdatedFilterPredicateBuilderBase"),
        "Generated file should declare the IncrementallyUpdatedFilterPredicateBuilder class.");
    assertTrue(content.contains("public IncrementallyUpdatedFilterPredicateBuilder(List<PrimitiveColumnIO> leaves)"),
        "Generated file should contain the constructor that takes leaves.");

    // Ensure presence of some key generation targets (Eq/NotEq/Contains/UserDefined paths)
    assertTrue(content.contains("Contains") || content.contains("ContainsPredicate"),
        "Generated file should include Contains-related code and predicates.");
    assertTrue(content.contains("UserDefined") || content.contains("visit(UserDefined"),
        "Generated file should include UserDefined predicate handling.");

    // Ensure header comment indicates auto-generation
    assertTrue(content.contains("auto-generated by org.apache.parquet.filter2.IncrementallyUpdatedFilterPredicateGenerator"),
        "Generated file should be labeled as auto-generated by the generator.");
  }

